const [runtime, workflow] = await Promise.all([
  pi.read('/home/balauru/.pi-profiles/fabric/skills/fabric-research/references/runtime.md'),
  pi.read('/home/balauru/.pi-profiles/fabric/npm/node_modules/pi-fabric/skillsets/typescript/fabric-workflow/SKILL.md')
]);
return {runtime, workflow};

const [fixtures, profile, models, catalog] = await Promise.all([
  Promise.all([
    pi.read('/home/balauru/.pi-profiles/fabric/tmp/research-workflow-revision-1788799764350/fixtures/alpha.md'),
    pi.read('/home/balauru/.pi-profiles/fabric/tmp/research-workflow-revision-1788799764350/fixtures/beta.md'),
  ]),
  pi.bash({cmd:'printf "cwd=%s\\nprofile=%s\\n" "$PWD" "$(printenv PI_CODING_AGENT_DIR)"'}),
  tools.models(),
  tools.list(),
]);
const modelText = JSON.stringify(models);
const native = JSON.stringify(catalog).match(/agents[^\"]*/g)?.slice(0,20) ?? [];
return {
  fixtureBytes: fixtures.map(x => x.length),
  profile: profile.output.trim(),
  requiredModelPresent: modelText.includes('openai-codex/gpt-5.6-terra'),
  agentRefs: native,
};

const [spawn, wait, status] = await Promise.all([
  tools.describe({ref:'agents.spawn'}),
  tools.describe({ref:'agents.wait'}),
  tools.describe({ref:'agents.status'}),
]);
return {spawn, wait, status};

const root = '/home/balauru/.pi-profiles/fabric';
const fixtureRoot = `${root}/tmp/research-workflow-revision-1788799764350/fixtures`;
const run = `${root}/runs/research-workflow-fixture-${Date.now()}`;
const executionResult = `${root}/tmp/research-workflow-revision-1788799764350/execution-result.md`;
const contracts = {
  streams: `${root}/skills/fabric-research/references/stream-contracts.md`,
  synthesis: `${root}/skills/fabric-research/references/synthesis-and-reporting.md`,
};
const alphaPath = `${run}/streams/alpha.md`;
const betaPath = `${run}/streams/beta.md`;
const researchPath = `${run}/RESEARCH.md`;
const reportPath = `${run}/REPORT.md`;
const statePath = `${run}/state.json`;

type Assignment = { role: string; ownedPath: string; reserved: boolean; id?: string; status: string; error?: string };
type Control = {
  phase: string;
  allowances: { maximumLaunches: number; reservedDownstream: number; launchesAttempted: number; repairCyclesAllowed: number; repairCyclesUsed: number };
  assignments: Record<string, Assignment>;
  ownedPaths: string[];
  coverage: Record<string, string>;
  nextActions: string[];
  nativeCapabilityBlocked: boolean;
};
const state: Control = {
  phase: 'initializing',
  allowances: { maximumLaunches: 7, reservedDownstream: 3, launchesAttempted: 0, repairCyclesAllowed: 1, repairCyclesUsed: 0 },
  assignments: {
    alpha: { role: 'researcher', ownedPath: alphaPath, reserved: false, status: 'planned' },
    beta: { role: 'researcher', ownedPath: betaPath, reserved: false, status: 'planned' },
    verifier: { role: 'verifier', ownedPath: researchPath, reserved: false, status: 'planned' },
    synthesizer: { role: 'synthesizer', ownedPath: reportPath, reserved: false, status: 'planned' },
    validator: { role: 'report-validator', ownedPath: researchPath, reserved: false, status: 'planned' },
  },
  ownedPaths: [researchPath, reportPath, statePath, alphaPath, betaPath],
  coverage: { Q1: 'pending', Q2: 'pending', Q3: 'pending', Q4: 'pending', Q5: 'pending' },
  nextActions: ['dispatch exactly two named research streams: alpha and beta'],
  nativeCapabilityBlocked: false,
};
const saveState = async () => { await pi.write({path: statePath, text: `${JSON.stringify(state, null, 2)}\n`}); };
const safeStatus = (value: unknown) => {
  if (value && typeof value === 'object') {
    const x = value as Record<string, unknown>;
    for (const key of ['status', 'state', 'phase']) if (typeof x[key] === 'string') return x[key] as string;
  }
  return 'wait-returned';
};
const findBoolean = (value: unknown, key: string): boolean | undefined => {
  if (!value || typeof value !== 'object') return undefined;
  const x = value as Record<string, unknown>;
  if (typeof x[key] === 'boolean') return x[key] as boolean;
  for (const v of Object.values(x)) { const found = findBoolean(v, key); if (found !== undefined) return found; }
  return undefined;
};
const exists = async (path: string) => (await pi.bash({cmd: `test -f ${JSON.stringify(path)} && printf yes || printf no`})).output.trim() === 'yes';

await workflow.configure({name: 'Synthetic research workflow smoke test', description: 'Two-stream local-fixture comparison with independent verification and validation'});
await phase('Initialize dossier', {total: 1});
const create = await pi.bash({cmd: `set -eu\nbase=${JSON.stringify(root + '/runs')}\nrun=${JSON.stringify(run)}\n[ ! -e "$run" ]\n[ ! -L "$base" ]\nmkdir -p "$run/streams"`});
if (!create.ok) throw new Error(`Could not create fresh dossier: ${create.output}`);
await pi.write({path: researchPath, text: `# Research brief\n\n## Scope\nSynthetic smoke-test dossier. The complete authorized evidence corpus is local only: [alpha fixture](${fixtureRoot}/alpha.md) and [beta fixture](${fixtureRoot}/beta.md). Do not use web, network, real-product claims, or sources outside these fixtures.\n\n## Decision\nCompare Alpha and Beta for dependency mapping, delivery governance, decision records, and practical effectiveness. Assess whether Beta's reported 90% is sufficient to prefer it over Alpha's 80%, identify unknowns, and state what evidence would resolve the choice.\n\n## Required questions\n- Q1: What evidence does each fixture provide about dependency mapping?\n- Q2: What evidence does each fixture provide about delivery governance?\n- Q3: What evidence does each fixture provide about decision records?\n- Q4: What evidence supports practical effectiveness, including the 80% and 90% figures?\n- Q5: Is the numerical difference decision-sufficient under this corpus, and what remains unknown or would resolve it?\n\n## Assignments\n- alpha owns [streams/alpha.md](streams/alpha.md).\n- beta owns [streams/beta.md](streams/beta.md).\n\nState and launch accounting: [state.json](state.json).\n\n### Verification (pending)\n\n### Report validation (pending)\n`});
await pi.write({path: reportPath, text: `# Comparison report\n\nStatus: in progress.\n`});
await saveState();

const common = {runner: 'pi' as const, model: 'openai-codex/gpt-5.6-terra', thinking: 'high' as const, extensions: true, recursive: false, cwd: root, tools: ['read', 'grep', 'find', 'ls', 'write', 'edit']};
const launch = async (key: string, task: string, schema?: object) => {
  const assignment = state.assignments[key];
  if (state.allowances.launchesAttempted >= state.allowances.maximumLaunches) throw new Error('Launch allowance exhausted');
  assignment.reserved = true;
  assignment.status = 'reserved';
  state.allowances.launchesAttempted += 1;
  await saveState();
  try {
    const spawned = await agents.spawn({...common, name: key, task, ...(schema ? {schema} : {})});
    const id = (spawned as {id?: string}).id;
    if (!id) throw new Error('Native spawn returned no durable ID');
    assignment.id = id;
    assignment.status = 'running';
    await saveState();
    return id;
  } catch (error) {
    assignment.status = 'launch-failed';
    assignment.error = error instanceof Error ? error.message : String(error);
    await saveState();
    return undefined;
  }
};
const wait = async (key: string, id: string | undefined) => {
  if (!id) return undefined;
  try {
    const result = await agents.wait({id});
    state.assignments[key].status = safeStatus(result);
    await saveState();
    return result;
  } catch (error) {
    state.assignments[key].status = 'wait-failed';
    state.assignments[key].error = error instanceof Error ? error.message : String(error);
    await saveState();
    return undefined;
  }
};

await phase('Research', {total: 2});
state.phase = 'research-dispatch'; state.nextActions = ['await alpha and beta', 'independent verification']; await saveState();
const researcherTask = (name: 'alpha' | 'beta', source: string, owned: string) => `You are the ${name} research stream in a bounded synthetic-fixture research workflow. Read your role contract in full: ${contracts.streams}. Then inspect only ${source}.\n\nQuestion: extract and qualify fixture-supported evidence about dependency mapping, delivery governance, decision records, and practical effectiveness. Record the exact local source path and clearly label all provenance as synthetic. Preserve uncertainties, definitions, denominators, comparison limits, and what this fixture cannot establish.\n\nOwn only ${owned}; write a readable Markdown evidence note there. Do not write state.json, RESEARCH.md, REPORT.md, fixtures, skills, configuration, or any other path. No web/network calls, installs, credentials, or delegation. Do not infer real-product behavior. Stop after the fixture is fully inspected and your owned note is saved. Return only a short saved-path/status handoff.`;
const alphaId = await launch('alpha', researcherTask('alpha', `${fixtureRoot}/alpha.md`, alphaPath), undefined);
const betaId = await launch('beta', researcherTask('beta', `${fixtureRoot}/beta.md`, betaPath), undefined);
const [alphaResult, betaResult] = await Promise.all([wait('alpha', alphaId), wait('beta', betaId)]);
state.phase = 'research-complete';
state.coverage.Q1 = (await exists(alphaPath)) && (await exists(betaPath)) ? 'stream evidence saved; pending verification' : 'partial stream evidence';
state.coverage.Q2 = state.coverage.Q1; state.coverage.Q3 = state.coverage.Q1; state.coverage.Q4 = state.coverage.Q1;
await saveState();
await workflow.event({message: 'Research streams reached terminal wait states', level: 'info'});

await phase('Verify evidence', {total: 1});
state.phase = 'verification-dispatch'; state.nextActions = ['verify actual stream artifacts', 'synthesize qualified comparison']; await saveState();
const verifierSchema = {type: 'object', properties: {status: {type: 'string', enum: ['complete', 'partial']}, repairNeeded: {type: 'boolean'}, summary: {type: 'string', maxLength: 500}}, required: ['status', 'repairNeeded', 'summary'], additionalProperties: false};
const verifierTask = `You are the independent verifier. Read your role contract in full: ${contracts.synthesis}. Read ${researchPath}, ${alphaPath}, and ${betaPath} if present, then inspect the cited local fixtures only as necessary to check decisive claims. The fixtures are the complete authorized synthetic corpus: no web/network or outside sources.\n\nVerify Q1-Q5 from the brief, reconcile Alpha/Beta claims, and apply evidence/reporting gates. Because this corpus is complete and exactly two named research streams are fixed, do not request or perform repair; identify decision-changing unknowns as unresolved. Take ownership of ${researchPath} after the researchers are terminal: replace only the pending Verification section with readable dispositions, cited local links, and gaps. Do not alter state.json, REPORT.md, streams, fixtures, skills, configuration, or other paths. No delegation. Return the requested compact control object only after saving the section.`;
const verifierId = await launch('verifier', verifierTask, verifierSchema);
const verifierResult = await wait('verifier', verifierId);
const verifierRepair = findBoolean(verifierResult, 'repairNeeded');
state.phase = 'verification-complete';
state.coverage.Q5 = (await exists(researchPath)) ? 'verified disposition recorded; fixture-bounded unknowns retained' : 'verification artifact missing';
state.nextActions = verifierRepair === true ? ['repair request rejected: corpus and stream count are fixed', 'synthesize qualified result'] : ['synthesize qualified result'];
await saveState();

await phase('Synthesize report', {total: 1});
state.phase = 'synthesis-dispatch'; await saveState();
const synthSchema = {type: 'object', properties: {status: {type: 'string', enum: ['written']}, reportPath: {type: 'string'}}, required: ['status', 'reportPath'], additionalProperties: false};
const synthTask = `You are the synthesizer. Read your role contract in full: ${contracts.synthesis}. Read ${researchPath}, ${alphaPath}, ${betaPath}, and the local fixtures only through their documented citations when needed.\n\nWrite a standalone report to ${reportPath}. It must compare Alpha and Beta on dependency mapping, delivery governance, decision records, and practical effectiveness; directly answer whether Beta's 90% is enough to prefer it over Alpha's 80%; distinguish what the synthetic fixture evidence establishes from unknowns; and list specific evidence that would resolve the choice. Cite local dossier/fixture paths and clearly state synthetic provenance. Do not introduce unverified recommendations or real-product claims.\n\nYou own only REPORT.md now. Do not modify state.json, RESEARCH.md, streams, fixtures, skills, configuration, or other paths. No web/network, installs, credentials, or delegation. Return the compact saved-path object only after writing the report.`;
const synthId = await launch('synthesizer', synthTask, synthSchema);
const synthResult = await wait('synthesizer', synthId);
state.phase = 'synthesis-complete'; state.nextActions = ['independent report validation']; await saveState();

const validatorSchema = {type: 'object', properties: {accepted: {type: 'boolean'}, actionableCorrections: {type: 'boolean'}, reason: {type: 'string', maxLength: 500}}, required: ['accepted', 'actionableCorrections', 'reason'], additionalProperties: false};
const validate = async (key: string, correction: boolean) => {
  const task = `You are the independent report validator${correction ? ' after a correction' : ''}. Read your role contract in full: ${contracts.synthesis}. Read ${reportPath}, ${researchPath}, ${alphaPath}, and ${betaPath} if present. Validate actual saved content against Q1-Q5: support for decisive claims, qualified 90% versus 80% conclusion, synthetic/local provenance, unknowns and resolving evidence, local links, and no unsupported real-product claims.\n\nTake ownership of ${researchPath} only after verifier and synthesizer are terminal. Replace the pending Report validation section${correction ? ' or append a dated follow-up validation subsection' : ''} with acceptance or specific failed checks and actual stop reason. Do not modify REPORT.md, state.json, streams, fixtures, skills, configuration, or any other path. No web/network, installs, credentials, or delegation. Return only the compact control object.`;
  const id = await launch(key, task, validatorSchema);
  return await wait(key, id);
};

await phase('Validate report', {total: 1});
state.phase = 'validation-dispatch'; await saveState();
const validationResult = await validate('validator', false);
let accepted = findBoolean(validationResult, 'accepted') === true;
let correctionUsed = false;
if (!accepted && findBoolean(validationResult, 'actionableCorrections') === true && state.allowances.launchesAttempted + 2 <= state.allowances.maximumLaunches) {
  correctionUsed = true; state.allowances.repairCyclesUsed = 1;
  state.assignments['report-correction'] = {role: 'report-correction', ownedPath: reportPath, reserved: false, status: 'planned'};
  state.assignments['validator-followup'] = {role: 'report-validator', ownedPath: researchPath, reserved: false, status: 'planned'};
  state.phase = 'report-correction-dispatch'; state.nextActions = ['one bounded report correction', 'follow-up independent validation']; await saveState();
  const correctionTask = `You are the sole bounded report-correction writer. Read ${contracts.synthesis}, ${reportPath}, ${researchPath}, ${alphaPath}, and ${betaPath}. Correct only the validator's actionable failures in ${reportPath}, retaining supported evidence and qualifications. The corpus is synthetic and local-only; do not add external claims. Own only REPORT.md. Do not modify state.json, RESEARCH.md, streams, fixtures, skills, configuration, or any other path. No web/network, installs, credentials, or delegation. Return a short saved-path/status handoff.`;
  const correctionId = await launch('report-correction', correctionTask, synthSchema);
  await wait('report-correction', correctionId);
  const followup = await validate('validator-followup', true);
  accepted = findBoolean(followup, 'accepted') === true;
}
state.phase = 'terminal';
state.nextActions = accepted ? ['stop: report accepted'] : ['stop: report not accepted or validation result unavailable'];
for (const q of Object.keys(state.coverage)) if (state.coverage[q].startsWith('stream evidence') || state.coverage[q].startsWith('verified')) state.coverage[q] = accepted ? 'accepted in validated fixture-bounded report' : 'reported but not accepted by validator';
await saveState();
await workflow.event({message: accepted ? 'Report accepted by independent validator' : 'Report validation did not establish acceptance', level: accepted ? 'success' : 'warning'});

const artifactChecks = {report: await exists(reportPath), research: await exists(researchPath), state: await exists(statePath), alpha: await exists(alphaPath), beta: await exists(betaPath)};
const resultStatus = accepted && Object.values(artifactChecks).every(Boolean) ? 'complete' : 'partial';
const executionText = `# Execution result\n\n- Run: ${run}\n- Status: ${resultStatus}\n- Observed phases: initialization=${artifactChecks.research && artifactChecks.state ? 'artifacts-created' : 'incomplete'}; alpha=${state.assignments.alpha.status}; beta=${state.assignments.beta.status}; verification=${state.assignments.verifier.status}; synthesis=${state.assignments.synthesizer.status}; validation=${state.assignments.validator.status}${correctionUsed ? '; one report-correction cycle used' : ''}.\n- Native capability blocked execution: no. Required model and native agent launch capability were observed during preflight.\n- Limitations: synthetic local fixtures were the complete corpus; no web/network retrieval was attempted. Validation acceptance=${accepted}.\n`;
await pi.write({path: executionResult, text: executionText});
return {
  status: resultStatus,
  runPath: run,
  paths: {report: reportPath, research: researchPath, state: statePath, executionResult},
  artifacts: artifactChecks,
  observed: {alpha: state.assignments.alpha.status, beta: state.assignments.beta.status, verifier: state.assignments.verifier.status, synthesizer: state.assignments.synthesizer.status, validator: state.assignments.validator.status, validationAccepted: accepted, correctionUsed, launches: state.allowances.launchesAttempted},
  nativeCapabilityBlocked: false,
  limitations: 'Synthetic local fixtures only; no repair requested or launched for evidence gaps outside the complete authorized corpus.'
};
